// POST /api/generate-images
// Body: { topicId }
// Phase 2: For each variation of a topic, generate an article image using
//   GPT-4o Vision (ref images embedded) → DALL-E 3 → save URL to Supabase
// Runs outside the 60s limit via a separate call from the UI

export const config = { maxDuration: 300 };

const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL || process.env.SUPABASE_URL || 'https://vfgujkocemgezvcuixpp.supabase.co';
const SUPABASE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InZmZ3Vqa29jZW1nZXp2Y3VpeHBwIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzQ1NjA4MTEsImV4cCI6MjA5MDEzNjgxMX0.-IxXJw7St2pLKSXKDU3dunJdgIkL-bhobD53SS-ci1s';

const sbHeaders = {
  apikey: SUPABASE_KEY,
  Authorization: `Bearer ${SUPABASE_KEY}`,
  'Content-Type': 'application/json',
};

// 脳手郎 reference images — 512px compressed, embedded directly
const NOUTERO_REFS = [
  { data: '', type: 'image/jpeg' },
  { data: '', type: 'image/jpeg' },
  { data: '', type: 'image/jpeg' },
  { data: '', type: 'image/jpeg' },
];

const POSITION_SCENES = {
  top:    'dramatic hero pose — 脳手郎 stands tall in a bold, attention-grabbing opening shot',
  middle: 'action scene — 脳手郎 is actively demonstrating or explaining the article\'s key insight',
  bottom: 'triumphant celebration — 脳手郎 cheers success, encouraging the reader to take action',
};

// Pass reference images DIRECTLY to gpt-image-1 via Responses API
// No text-description middleman — the model sees the actual character photos
async function generateArticleImage(variation, position = 'top') {
  const blogTitle = variation.blog_title || variation.summary || '';
  const body = (variation.blog_body || variation.body_mail || '').slice(0, 300);
  const scene = POSITION_SCENES[position];

  const prompt = `The attached photos are reference images of our mascot character "脳手郎" (Noutero) — a gold 3D figurine with a pink brain on its head, blue beak/mustache, and a metallic gold body.

Generate a blog article image for a Japanese business newsletter:
- Article title: ${blogTitle}
- Article theme: ${body}
- Scene: ${scene}

Requirements:
- Reproduce 脳手郎 EXACTLY as shown in the reference photos (same gold body, brain, blue beak)
- Photorealistic, cinematic dramatic lighting
- 3D collectible figurine render quality, epic atmosphere
- Japanese business context (subsidies, consulting)
- NO text or lettering anywhere in the image`;

  const response = await fetch('https://api.openai.com/v1/responses', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${process.env.OPENAI_API_KEY}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      model: 'gpt-4o',
      input: [
        {
          role: 'user',
          content: [
            { type: 'input_text', text: prompt },
            ...NOUTERO_REFS.map(ref => ({
              type: 'input_image',
              image_url: `data:${ref.type};base64,${ref.data}`,
            })),
          ],
        },
      ],
      tools: [{ type: 'image_generation' }],
    }),
  });

  if (!response.ok) {
    const err = await response.json();
    throw new Error(`Responses API error: ${err.error?.message}`);
  }

  const data = await response.json();
  console.log('[generate-images] response output types:', data.output?.map(o => o.type));

  // Find image generation output
  const imgCall = data.output?.find(o => o.type === 'image_generation_call');
  if (imgCall?.result) return imgCall.result;

  // Fallback: check message content for image
  const msg = data.output?.find(o => o.type === 'message');
  const imgContent = msg?.content?.find(c => c.type === 'image_url' || c.type === 'image');
  return imgContent?.b64_json || imgContent?.image_url || null;
}

async function updateVariation(id, imageUrls) {
  const urls = Array.isArray(imageUrls) ? imageUrls : [imageUrls];
  const r = await fetch(`${SUPABASE_URL}/rest/v1/magazine_variations?id=eq.${id}`, {
    method: 'PATCH',
    headers: sbHeaders,
    body: JSON.stringify({ blog_image_url: urls[0] || null, blog_image_urls: urls }),
  });
  if (!r.ok) {
    const err = await r.text();
    console.error(`[updateVariation] PATCH failed (${r.status}):`, err);
    throw new Error(`Supabase PATCH failed: ${r.status}`);
  }
}

async function uploadToStorage(b64Data, variationId) {
  const buffer = Buffer.from(b64Data, 'base64');

  const fileName = `article-images/v${variationId}-${Date.now()}.png`;
  const uploadUrl = `${SUPABASE_URL}/storage/v1/object/magazine-media/${fileName}`;
  const r = await fetch(uploadUrl, {
    method: 'POST',
    headers: {
      apikey: SUPABASE_KEY,
      Authorization: `Bearer ${SUPABASE_KEY}`,
      'Content-Type': 'image/png',
      'x-upsert': 'true',
    },
    body: buffer,
  });
  if (!r.ok) {
    const err = await r.text();
    throw new Error(`Storage upload failed (${r.status}): ${err}`);
  }
  return `${SUPABASE_URL}/storage/v1/object/public/magazine-media/${fileName}`;
}

export default async function handler(req, res) {
  if (req.method !== 'POST') return res.status(405).end();

  const { topicId, variationId } = req.body;
  if (!topicId) return res.status(400).json({ error: 'topicId is required' });
  if (!process.env.OPENAI_API_KEY) return res.status(500).json({ error: 'OPENAI_API_KEY not set' });

  const log = [];
  const step = (msg) => { log.push(msg); console.log('[generate-images]', msg); };

  try {
    // Fetch all variations for this topic
    step('📋 バリエーション取得中...');
    const r = await fetch(`${SUPABASE_URL}/rest/v1/magazine_variations?topic_id=eq.${topicId}&select=id,variation_no,summary,body_mail,blog_title,blog_body`, {
      headers: sbHeaders,
    });
    let variations = await r.json();
    if (!Array.isArray(variations) || variations.length === 0) {
      return res.status(404).json({ error: 'No variations found for this topic' });
    }
    if (variationId) {
      variations = variations.filter(v => v.id === variationId);
      if (variations.length === 0) return res.status(404).json({ error: 'Variation not found' });
    }
    step(`✅ ${variations.length}記事取得`);

    // Generate images — reference photos passed directly to model (no text middleman)
    step('🎨 参考画像を直接モデルに投入して生成開始...');
    const results = [];
    for (const v of variations) {
      step(`🖼️ 画像生成中 #${v.variation_no} (上・中・下 3枚)...`);
      try {
        const imageUrls = [];
        for (const pos of ['top', 'middle', 'bottom']) {
          step(`  📸 #${v.variation_no} [${pos}] 生成中...`);
          const b64 = await generateArticleImage(v, pos);
          if (b64) {
            const imageUrl = await uploadToStorage(b64, `${v.id}-${pos}`);
            imageUrls.push(imageUrl);
            step(`  ✅ #${v.variation_no} [${pos}] 完了`);
          } else {
            step(`  ⚠️ #${v.variation_no} [${pos}] データなし`);
          }
        }
        if (imageUrls.length > 0) {
          await updateVariation(v.id, imageUrls);
          results.push({ variationId: v.id, variation_no: v.variation_no, imageUrls });
          step(`✅ #${v.variation_no} 全${imageUrls.length}枚完了`);
        } else {
          results.push({ variationId: v.id, variation_no: v.variation_no, imageUrls: [] });
        }
      } catch (e) {
        step(`❌ #${v.variation_no} エラー: ${e.message}`);
        results.push({ variationId: v.id, variation_no: v.variation_no, error: e.message });
      }
    }

    return res.status(200).json({ success: true, results, log });
  } catch (err) {
    console.error('[generate-images] error:', err);
    return res.status(500).json({ error: err.message, log });
  }
}
